#pragma once

#include "shared/item_stack.h"

#include <algorithm>
#include <array>
#include <cstdint>
#include <span>
#include <string_view>

namespace KCDC::Shared::Game {
    /**
     * One `MeleeWeapon` of `Libs/Tables/item/item*.xml`: what the hit
     * calculation reads of the weapon a blow was struck with, and of the one
     * that blocked it.
     *
     * Generated by `tools/generate_combat_catalog.py`; the server has no game
     * module to read the item tables from.
     */
    struct CombatWeaponEntry {
        RPC::ItemClassId itemClass;

        /** `Attack`, before condition, strength and skill. */
        float attack;

        /** `AttackModStab`, `AttackModSlash`, `AttackModSmash`: the share of the attack each damage pass gets. */
        std::array<float, 3> attackMods;

        /** `Defense`: what the weapon puts up when it blocks. */
        float defense;

        /** `StrReq`, `AgiReq`. */
        std::int32_t strengthRequirement;
        std::int32_t agilityRequirement;

        /** `Class` (a `weapon_class.xml` id) and `SubClass`. */
        std::int32_t weaponClass;
        std::int32_t subClass;
    };

    /** One `Armor`, `Helmet` or `Hood`: its three defences and the armour archetype its `Clothing` resolves to. */
    struct CombatArmorEntry {
        RPC::ItemClassId itemClass;

        /** `DefenseStab`, `DefenseSlash`, `DefenseSmash`. */
        std::array<float, 3> defense;

        /** The nearest ancestor-or-self `Clothing` of `CharacterComponent.xml` that names an `ArmorArchetypeId`, or -1. */
        std::int32_t archetype;
    };

    /** One `MeleeWeaponClass` of `weapon_class.xml`: the skill it trains, by the game's own name. */
    struct CombatWeaponClassEntry {
        std::int32_t id;
        std::string_view skill;
    };

    /** One `body_subpart.xml` row: its limb's `body_damage_coeff`, and whether that limb is the head. */
    struct CombatSubpartEntry {
        std::int32_t id;
        float damageCoefficient;
        bool head;
    };

    /** How much of a body an armour archetype covers: `body_subpart_importance` summed over its rows. */
    struct CombatArchetypeCoverage {
        std::int32_t archetype;
        float coverage;
    };

    /** An armour archetype covering a subpart, on some layer. */
    struct CombatArchetypeSubpart {
        std::int32_t archetype;
        std::int32_t subpart;

        auto operator<=>(const CombatArchetypeSubpart &) const = default;
    };

    /** One `combat_attack_type.xml` row. */
    struct CombatAttackTypeEntry {
        std::int32_t id;
        float relativeStaminaCost;

        /** `rpg_damage_type_id`: the damage-pass mask itself, stab 1, slash 2, smash 4. */
        std::int32_t damageTypes;

        /** `cannot_kill`: the attack knocks out where it would kill. */
        bool cannotKill;
    };

    /** One `combat_damage_type_mapping.xml` row: a weapon class (and subclass) that runs other passes for an attack type. -1 matches any. */
    struct CombatDamageTypeMapping {
        std::int32_t attackType;
        std::int32_t weaponClass;
        std::int32_t subClass;
        std::int32_t damageTypes;
    };

    /** The `soul_archetype.xml` columns a blow reads of a player. */
    struct CombatSoulArchetype {
        std::int32_t id;

        /** `body_base_armor`: armour the bare body adds on every subpart. */
        float bodyBaseArmor;

        /** `unarmed_attack_base`: a fist's attack before strength and skill. */
        float unarmedAttackBase;
    };

    /** Sorted by binary class. */
    extern const std::span<const CombatWeaponEntry> g_CombatWeapons;

    /** Sorted by binary class. */
    extern const std::span<const CombatArmorEntry> g_CombatArmor;

    /** Sorted by id. */
    extern const std::span<const CombatWeaponClassEntry> g_CombatWeaponClasses;

    /** Sorted by id. */
    extern const std::span<const CombatSubpartEntry> g_CombatSubparts;

    extern const std::span<const CombatArchetypeCoverage> g_CombatArchetypeCoverage;

    /** Sorted. */
    extern const std::span<const CombatArchetypeSubpart> g_CombatArchetypeSubparts;

    /** Sorted by id. */
    extern const std::span<const CombatAttackTypeEntry> g_CombatAttackTypes;

    extern const std::span<const CombatDamageTypeMapping> g_CombatDamageTypeMappings;

    /** `Hero` (13), the player's own archetype, and `Hero_female` (15), which a female player is swapped to. */
    extern const CombatSoulArchetype g_CombatHeroArchetype;
    extern const CombatSoulArchetype g_CombatHeroFemaleArchetype;

    /** `body_subpart_importance` summed over the human body: what an archetype's coverage is a share of. */
    extern const float g_CombatHumanBodyImportance;

    /** Weapon class 8, `shield`; 17, `shield_broken`, is not one. */
    inline constexpr std::int32_t kShieldWeaponClass = 8;

    template <typename TEntry>
    const TEntry *FindCombatItem(std::span<const TEntry> entries, const RPC::ItemClassId &itemClass) {
        const auto found = std::lower_bound(entries.begin(), entries.end(), itemClass, [](const TEntry &entry, const RPC::ItemClassId &key) {
            return entry.itemClass < key;
        });
        return found != entries.end() && found->itemClass == itemClass ? &*found : nullptr;
    }

    inline const CombatWeaponEntry *FindCombatWeapon(const RPC::ItemClassId &itemClass) {
        return FindCombatItem(g_CombatWeapons, itemClass);
    }

    inline const CombatArmorEntry *FindCombatArmor(const RPC::ItemClassId &itemClass) {
        return FindCombatItem(g_CombatArmor, itemClass);
    }

    inline const CombatWeaponClassEntry *FindCombatWeaponClass(std::int32_t id) {
        for (const CombatWeaponClassEntry &entry : g_CombatWeaponClasses) {
            if (entry.id == id) {
                return &entry;
            }
        }
        return nullptr;
    }

    inline const CombatSubpartEntry *FindCombatSubpart(std::int32_t id) {
        for (const CombatSubpartEntry &entry : g_CombatSubparts) {
            if (entry.id == id) {
                return &entry;
            }
        }
        return nullptr;
    }

    inline const CombatAttackTypeEntry *FindCombatAttackType(std::int32_t id) {
        for (const CombatAttackTypeEntry &entry : g_CombatAttackTypes) {
            if (entry.id == id) {
                return &entry;
            }
        }
        return nullptr;
    }

    /** `ArchetypeCoverage`: 0 for an archetype no row names. */
    inline float CombatArchetypeCoverageOf(std::int32_t archetype) {
        for (const CombatArchetypeCoverage &entry : g_CombatArchetypeCoverage) {
            if (entry.archetype == archetype) {
                return entry.coverage;
            }
        }
        return 0.0F;
    }

    /** Whether `archetype` covers `subpart` on any layer (0x18075453C). */
    inline bool CombatArchetypeCovers(std::int32_t archetype, std::int32_t subpart) {
        return std::binary_search(g_CombatArchetypeSubparts.begin(), g_CombatArchetypeSubparts.end(), CombatArchetypeSubpart {archetype, subpart});
    }

    /**
     * The damage passes an attack type runs with a weapon (0x181464F14): a
     * mapping row for the weapon's class and subclass, else the attack
     * type's own. 0 for an attack type with no row.
     */
    inline std::int32_t CombatDamageTypesOf(std::int32_t attackType, std::int32_t weaponClass, std::int32_t subClass) {
        for (const CombatDamageTypeMapping &mapping : g_CombatDamageTypeMappings) {
            if (mapping.attackType == attackType && (mapping.weaponClass == weaponClass || mapping.weaponClass == -1) && (mapping.subClass == subClass || mapping.subClass == -1)) {
                return mapping.damageTypes;
            }
        }
        const CombatAttackTypeEntry *row = FindCombatAttackType(attackType);
        return row != nullptr ? row->damageTypes : 0;
    }
} // namespace KCDC::Shared::Game
